SELECT p.gender, p.anchor_age, p.anchor_year, p.anchor_year_group, i.discharge_location, percentile_cont(0.5) within GROUP (ORDER BY i.los) AS p50, percentile_cont(0.75) within GROUP (ORDER BY i.los) AS p75, percentile_cont(0.90) within GROUP (ORDER BY i.los) AS p90, percentile_cont(0.95) within GROUP (ORDER BY i.los) AS p95 FROM patients p JOIN icustays i ON p.subject_id = i.subject_id WHERE p.gender = 'F' AND p.anchor_age BETWEEN 40 AND 50 AND i.discharge_location IN ('home', 'hospice', 'in-hospital death') AND i.dischtime - i.admitime <= 7 GROUP BY p.gender, p.anchor_age, p.anchor_year, p.anchor_year_group, i.discharge_location ORDER BY p.gender, p.anchor_age, p.anchor_year, p.anchor_year_group, i.discharge_location NULLS LAST;